CREATE TABLE p_priced_catalog(id TEXT PRIMARY KEY,sku TEXT NOT NULL COLLATE NOCASE UNIQUE,name TEXT NOT NULL,description TEXT NOT NULL,unit TEXT NOT NULL CHECK(unit IN ('hour','day','month','project','each')),unit_cents INTEGER NOT NULL CHECK(unit_cents>0 AND unit_cents<=1000000000),unit_cost_cents INTEGER CHECK(unit_cost_cents>=0 AND unit_cost_cents<=1000000000),version INTEGER NOT NULL DEFAULT 1,updated_by TEXT NOT NULL REFERENCES oa_operators(id),updated_at INTEGER NOT NULL);
